<?php
declare(strict_types=1);
$database=(string)getenv('MACCMS_TEST_DATABASE');if(!preg_match('/^maccms_ci_[a-z0-9_]+$/',$database)){fwrite(STDERR,"FAIL: disposable database required\n");exit(1);}$root=dirname(__DIR__,2);define('APP_PATH',$root.'/application/');define('ENTRANCE','command');$_SERVER['HTTP_HOST']='127.0.0.1';$_SERVER['SCRIPT_NAME']='/repair';require $root.'/thinkphp/base.php';\think\App::initCommon();
$id=(int)\think\Db::name('vod')->insertGetId(['type_id'=>1,'type_id_1'=>0,'vod_name'=>'Repair CI','vod_en'=>'repair-ci','vod_status'=>0,'vod_recycle_time'=>0,'vod_area'=>'Taiwan','vod_content'=>'']);\think\Db::name('vod_ext')->where('vod_id',$id)->delete();$before=\think\Db::name('content_job')->count();$service=new \app\common\util\ContentRepairService(function($limit)use($id){$row=\think\Db::name('vod')->where('vod_id',$id)->find();$row+=['has_extension'=>0,'workflow_status'=>'','merged_into_vod_id'=>0,'manual_locks'=>0,'has_ai_job'=>0];return [$row];});$dry=$service->run(false,false,10);if(\think\Db::name('vod_ext')->where('vod_id',$id)->count()!==0||\think\Db::name('content_job')->count()!==$before){fwrite(STDERR,"FAIL: dry-run mutated database\n");exit(1);}$service->run(true,true,10);if(\think\Db::name('vod_ext')->where('vod_id',$id)->count()!==1||\think\Db::name('content_job')->count()!==$before+1){fwrite(STDERR,"FAIL: apply did not repair extension and enqueue once\n");exit(1);}$service->run(true,true,10);if(\think\Db::name('content_job')->count()!==$before+1){fwrite(STDERR,"FAIL: repeated repair duplicated AI work\n");exit(1);}fwrite(STDOUT,"OK: content repair dry-run/apply passed on {$database}\n");
